const [hi, lo] = msg.payload;
const b = Buffer.alloc(4);
b.writeUInt16BE(hi, 0);
b.writeUInt16BE(lo, 2);
msg.payload = b.readFloatBE(0);
return msg;

const b = Buffer.alloc(4);
b.writeFloatBE(msg.value, 0);
msg.payload.value = [b.readUInt16BE(0), b.readUInt16BE(2)];
return msg;

global.set('ljm', {
  AIN0:                  { address:     0, quantity: 2, type: 'float32' },
  AIN0_RANGE:            { address: 40000, quantity: 2, type: 'float32' },
  AIN0_NEGATIVE_CH:      { address: 41000, quantity: 1, type: 'uint16'  },
  AIN0_RESOLUTION_INDEX: { address: 41500, quantity: 1, type: 'uint16'  },
  TEST:                  { address: 55100, quantity: 2, type: 'uint32'  },
});

// AIN0_RANGE:            10.0 | 1.0 | 0.1 | 0.01   (0.0 = default, ±10 V)
// AIN0_NEGATIVE_CH:      1 = differentielt mod AIN1,  199 = single-ended
// AIN0_RESOLUTION_INDEX: 0-8 paa T7, 0-12 paa T7-Pro  (0 = default)
// TEST:                  laeser altid 0x00112233

return null;

return [
    { payload: 250 },   // → AIN0_SETTLING_US
    { payload: 0.01 },   // → AIN0_RANGE
    { payload: 1 },   // → AIN0_NEGATIVE_CH
];

msg = {};

let visibleA = flow.get('cursorAvisible');
let cursorA = flow.get('cursorA');

let visibleB = flow.get('cursorBvisible');
let cursorB = flow.get('cursorB');

if (cursorA === undefined) {
    cursorA = 0;
    visibleA = false;
}

if (cursorB === undefined) {
    cursorB = 0;
    visibleB = false;
}

let opacityA = 0;
let opacityB = 0;

if (visibleA) {
    opacityA = 1;
}

if (visibleB) {
    opacityB = 1;
}

msg.ui_update = {
    chartOptions: {
        series: [
            {
                name: "Cursor A",
                type: "line",
                lineStyle: {
                    color: "red"
                },
                itemStyle: {
                    color: "red"
                },
                markLine: {
                    symbol: "none",
                    label: {
                        show: visibleA
                    },
                    data: [
                        {
                            name: "Cursor A",
                            yAxis: cursorA,
                            lineStyle: {
                                color: "red",
                                width: 2,
                                opacity: opacityA,
                                type: "dashed"
                            }
                        }
                    ]
                }
            },
            {
                name: "Cursor B",
                type: "line",
                lineStyle: {
                    color: "blue"
                },
                itemStyle: {
                    color: "blue"
                },
                markLine: {
                    symbol: "none",
                    label: {
                        show: visibleB
                    },
                    data: [
                        {
                            name: "Cursor B",
                            yAxis: cursorB,
                            lineStyle: {
                                color: "blue",
                                width: 2,
                                opacity: opacityB,
                                type: "dashed"
                            }
                        }
                    ]
                }
            }
        ]
    }
};

return msg;

const WINDOW = 4;                 // number of samples to average over
let value = msg.payload;

value = value * 1000;

// Add the new sample to the window
let buffer = flow.get('buffer');
if (buffer === undefined) {
    buffer = [];
}
buffer.push(value);
if (buffer.length > WINDOW) {
    buffer.shift();
}
flow.set('buffer', buffer);

// Mean
let sum = 0;
for (let i = 0; i < buffer.length; i++) {
    sum = sum + buffer[i];
}
const mean = sum / buffer.length;

// Standard deviation
let sumSquares = 0;
for (let i = 0; i < buffer.length; i++) {
    const diff = buffer[i] - mean;
    sumSquares = sumSquares + diff * diff;
}
const spread = Math.sqrt(sumSquares / buffer.length);

// Store them so the Mark buttons can just read them
flow.set('mean', mean);
flow.set('spread', spread);
flow.set('samples', buffer.length);


let returnvalue = parseFloat(value.toFixed(3));
msg.payload = returnvalue;
return msg;

let seconds = Number(msg.payload);

let chartNames = [
    "Strain chart short",
    "Strain chart medium",
    "Strain chart long"
];

let selectedChart = "";

if (seconds === 30) {
    selectedChart = "Strain chart short";
}

if (seconds === 60) {
    selectedChart = "Strain chart medium";
}

if (seconds === 300) {
    selectedChart = "Strain chart long";
}

if (selectedChart === "") {
    return null;
}

let hiddenCharts = [];

for (let name of chartNames) {
    if (name !== selectedChart) {
        hiddenCharts.push(name);
    }
}

msg.payload = {
    widgets: {
        show: [selectedChart],
        hide: hiddenCharts
    }
};

return msg;

const a = flow.get('cursorA');
const b = flow.get('cursorB');

let deltaV = null;

if (a !== undefined && b !== undefined ) {
    deltaV = b - a;
}

flow.set('deltaV', deltaV);

return { payload: deltaV };

const deltaV = flow.get('deltaV');          // mV, med fortegn
const gf = flow.get('gaugeFactor');
const vex = flow.get('excitation');      // volt

if (deltaV === null || deltaV === undefined) {
    return { payload: null };
}

const microStrain = 4000 * deltaV / (vex * gf);

flow.set('microStrain', microStrain);

return { payload: microStrain };
